import { categories, products, occasions, benefits, faqs, companyFacts, customizationWorkflow, customizationDemo } from './content.mjs';
import { galleryCategories, galleryItems } from './gallery-data.mjs';

export function renderPages(config, approved) {
  const esc = value => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
  const icon = name => `<svg aria-hidden="true"><use href="#icon-${name}"/></svg>`;
  const categoryFor = product => categories.find(category => category.slug === product.category);
  const displayPhone = config.whatsapp.startsWith('62') ? `+62 ${config.whatsapp.slice(2,5)}-${config.whatsapp.slice(5,9)}-${config.whatsapp.slice(9)}` : `+${config.whatsapp}`;
  const price = product => Number.isFinite(product.price) ? `Mulai dari ${new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(product.price)}` : 'Tanya harga';
  const wa = message => `https://wa.me/${config.whatsapp}?text=${encodeURIComponent(message)}`;
  const generic = `Halo Putri Florist! Saya ingin konsultasi rangkaian bunga untuk area ${config.city}. Bisa dibantu?`;
  const waLink = (label = 'Pesan via WhatsApp', message = generic, className = 'button', attributes = '') => `<a class="${className}" href="${wa(message)}" target="_blank" rel="noopener noreferrer" ${attributes}>${icon('wa')}${label}</a>`;
  const productWa = (product, className = 'text-link', label = 'Tanya & pesan') => waLink(label, `Halo Putri Florist!\n\nSaya tertarik dengan rangkaian ${product.name}.\n${price(product)}\nLink: ${config.siteUrl.replace(/\/$/, '')}/produk/${product.slug}\n\nBoleh dibantu desain, harga, dan ketersediaannya?`, className, `data-product-name="${esc(product.name)}" data-product-url="/produk/${product.slug}" data-product-price="${esc(price(product))}"`);
  const image = (key, alt, options = {}) => `<img src="/assets/catalog/${key}-960.webp" srcset="/assets/catalog/${key}-480.webp 480w, /assets/catalog/${key}-960.webp 960w" sizes="${options.sizes || '(max-width: 760px) 45vw, 25vw'}" width="960" height="1200" alt="${esc(alt)}" loading="${options.eager ? 'eager' : 'lazy'}" decoding="async"${options.eager ? ' fetchpriority="high"' : ''}>`;
  const arrowLink = (href, label) => `<a class="text-link" href="${href}">${label}${icon('arrow')}</a>`;
  const brand = approved.match(/    <a class="brand"[\s\S]*?    <\/a>/)[0].replace('href="./"', 'href="/"');
  const symbols = approved.match(/  <svg xmlns=[\s\S]*?<\/svg>/)[0];
  const originalHead = approved.match(/<head>([\s\S]*?)<\/head>/)[1];
  const originalMain = approved.match(/  <main>[\s\S]*?<\/main>/)[0];
  const homeDialog = approved.match(/  <dialog id="consultation"[\s\S]*?<\/dialog>/)[0];
  const originalScript = approved.match(/  <script>\s*([\s\S]*?)<\/script>/)[1];
  const pages = new Map();

  function header(active) {
    const links = [
      ['/', 'Beranda'],
      ['/produk', 'Produk'],
      ['/customize', 'Kustomisasi'],
      ['/galeri', 'Galeri'],
      ['/tentang', 'Tentang Kami'],
      ['/kontak', 'Kontak']
    ];
    const item = ([href, text]) => `<a class="nav-link" href="${href}"${active === href ? ' aria-current="page"' : ''}>${text}</a>`;
    const categoryLinks = categories.map(category => `<a href="/kategori/${category.slug}">${category.name}</a>`).join('');
    return `<header class="site-header">${brand}<nav class="desktop-nav" aria-label="Navigasi utama">${links.slice(0,2).map(item).join('')}<details class="nav-categories"><summary class="nav-link">Kategori<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></summary><div class="category-dropdown">${categoryLinks}</div></details>${links.slice(2).map(item).join('')}</nav><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-menu" aria-label="Buka menu navigasi"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8h16M4 16h16"/></svg></button></header><nav class="mobile-menu" id="mobile-menu" aria-label="Navigasi ponsel" hidden>${links.slice(0,2).map(item).join('')}<details><summary>Kategori</summary><div class="mobile-categories">${categoryLinks}</div></details>${links.slice(2).map(item).join('')}${waLink('Pesan via WhatsApp', generic, 'text-link')}</nav>`;
  }

  function footer() {
    const socialLinks = [['Instagram', config.instagram], ['Facebook', config.facebook]].filter(([,url]) => url).map(([name,url]) => `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('');
    return `<footer class="site-footer"><div class="footer-grid"><div class="footer-brand">${brand}<p>Putri Florist adalah digital-first floral commerce startup yang didirikan pada Januari 2026 di Jakarta, Indonesia. Kami merangkai bunga segar dan membangun pengalaman kustomisasi personal untuk setiap momen berharga.</p><div class="footer-badge"><span>Didirikan Januari 2026</span><span>Jakarta, Indonesia</span><span>Early-stage / Bootstrapped</span></div></div><div class="footer-column"><h2 class="section-heading">Jelajahi</h2><ul>${[['/','Beranda'],['/produk','Semua Produk'],['/customize','Kustomisasi Bunga'],['/galeri','Galeri Karya'],['/tentang','Tentang Kami'],['/kontak','Kontak & Pemesanan'],['/#faq','Tanya Jawab']].map(([url,label]) => `<li><a href="${url}">${label}</a></li>`).join('')}</ul></div><div class="footer-column"><h2 class="section-heading">Rangkaian</h2><ul>${categories.map(category=>`<li><a href="/kategori/${category.slug}">${category.name}</a></li>`).join('')}</ul></div><div class="footer-column"><h2 class="section-heading">Mari bercerita</h2><a class="footer-phone" href="${wa(generic)}" target="_blank" rel="noopener noreferrer">${displayPhone} ↗</a><p>Area layanan: ${esc(config.city)}, Indonesia<br>Konsultasi &amp; pesanan dilayani via WhatsApp.<br><span class="footer-email-note">Email domain resmi (@putriflorist.id) dalam konfigurasi mailbox.</span></p><div class="footer-social">${socialLinks || '<p>Media sosial<br><span>Akan hadir setelah akun resmi tersedia.</span></p>'}</div></div></div><div class="footer-bottom"><div class="footer-legal-links"><span>© 2026 Putri Florist. Hak cipta dilindungi.</span><span>·</span><a href="/privacy">Kebijakan Privasi</a><span>·</span><a href="/terms">Syarat &amp; Ketentuan</a></div><span class="footer-note">Didirikan Januari 2026 di Indonesia · Rangkaian dirangkai oleh florist nyata · Foto portofolio merupakan referensi inspirasi desain</span></div></footer>${waLink('<span>Chat WhatsApp</span>', generic, 'floating-chat', 'aria-label="Konsultasi melalui WhatsApp (tab baru)"')}`;
  }

  function finalCta() {
    return `<section class="final-cta"><div class="section-wrap"><div><h2 class="section-heading">Ada yang ingin kamu<br><em>sampaikan dengan bunga?</em></h2><p>Ceritakan momen dan keinginanmu. Mari temukan rangkaian yang paling berarti.</p></div>${waLink('Mari pilih bungamu', generic, 'button button-light')}</div></section>`;
  }

  function shell(path, title, description, body, { home = false, extra = '', imageKey = '' } = {}) {
    const fullTitle = home ? title : `${title} | Putri Florist`;
    let head = originalHead.replace(/<title>[\s\S]*?<\/title>/, `<title>${esc(fullTitle)}</title>`).replace(/<meta name="description"[^>]*>/, `<meta name="description" content="${esc(description)}">`);
    if (!home) head = head.replace(/\s*<link rel="preload" as="image"[^>]*>/, '');
    const canonical = config.siteUrl ? new URL(path, config.siteUrl).href : '';
    const shareImage = imageKey ? `/assets/catalog/${imageKey}-960.webp` : '/assets/hero-poster.png';
    head += `<link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="/site.css"><meta property="og:type" content="website"><meta property="og:locale" content="id_ID"><meta property="og:site_name" content="Putri Florist"><meta property="og:title" content="${esc(fullTitle)}"><meta property="og:description" content="${esc(description)}"><meta name="twitter:card" content="summary_large_image">${canonical ? `<link rel="canonical" href="${esc(canonical)}"><meta property="og:url" content="${esc(canonical)}"><meta property="og:image" content="${esc(new URL(shareImage, config.siteUrl).href)}">` : ''}`;
    const org = {
      '@context': 'https://schema.org',
      '@type': 'Organization',
      name: config.name,
      url: config.siteUrl || 'https://putriflorist.id',
      foundingDate: '2026-01',
      description: 'Putri Florist adalah floral-commerce startup Indonesia yang didirikan pada Januari 2026, menyediakan buket bunga, bunga papan, standing flower, dan pemesanan bunga custom.',
      telephone: `+${config.whatsapp}`,
      areaServed: config.city,
      contactPoint: {
        '@type': 'ContactPoint',
        telephone: `+${config.whatsapp}`,
        contactType: 'customer service',
        availableLanguage: ['id', 'en']
      }
    };
    let script = '';
    if (home) {
      const heroScript = originalScript.replace(/      const menuToggle =[\s\S]*?      const dialog =/, '      const menuToggle = document.querySelector(".menu-toggle");\n      const dialog =').replace('        setMenu(false);', '        window.closeMainMenu?.();');
      script = `<script>${heroScript}</script>`;
    }
    return `<!doctype html><html lang="id"><head>${head}<script type="application/ld+json">${JSON.stringify(org).replace(/</g,'\\u003c')}</script></head><body>${symbols}<a class="skip-link" href="${home ? '#hero' : '#page-content'}">Ke konten utama</a>${header(path === '/' ? '/' : path.startsWith('/produk') || path.startsWith('/kategori') ? '/produk' : path)}${body}${footer()}${extra}${home ? homeDialog : ''}<script src="/site-config.js"></script><script src="/app.js"></script>${script}</body></html>`;
  }

  function companyIntroSection() {
    return `<section class="company-intro-section" id="profil-startup"><div class="section-wrap"><div class="company-intro-grid"><div class="company-intro-lead"><p class="section-kicker">Digital-first Floral Commerce</p><h2 class="section-heading">Bunga personal.<br><em>Didirikan Januari 2026.</em></h2><p class="section-intro">Putri Florist adalah floral-commerce startup yang didirikan pada Januari 2026 di Jakarta, Indonesia. Kami mempermudah pemesanan bunga yang personal dan bermakna melalui pengalaman kustomisasi modern, didukung perangkaian langsung oleh florist nyata.</p><div class="company-cta-row"><a class="button button-light" href="/tentang">Tentang Putri Florist${icon('arrow')}</a><a class="button" href="/customize">Arah Kustomisasi AI (In Dev)${icon('arrow')}</a></div></div><div class="company-facts-card"><h3 class="facts-title">Profil Bisnis &amp; Verifikasi</h3><dl class="facts-list"><div><dt>Perusahaan</dt><dd>Putri Florist</dd></div><div><dt>Didirikan</dt><dd>Januari 2026</dd></div><div><dt>Basis Operasional</dt><dd>Jakarta, Indonesia</dd></div><div><dt>Tahap Bisnis</dt><dd>Early-stage / Bootstrapped</dd></div><div><dt>Fokus Utama</dt><dd>Digital floral commerce &amp; custom ordering</dd></div><div><dt>Kanal Layanan</dt><dd>Konsultasi &amp; Pemesanan WhatsApp</dd></div><div><dt>Pengembangan AI</dt><dd>Rekomendasi konsep floral (Dalam pengembangan)</dd></div></dl></div></div></div></section>`;
  }

  function categorySection() {
    return `<section id="kategori"><div class="section-wrap"><div class="section-head"><div><p class="section-kicker">01 / Temukan bentuk ceritamu</p><h2 class="section-heading">Beragam bunga.<br><em>Satu bahasa hati.</em></h2></div>${arrowLink('/produk','Jelajahi semua rangkaian')}</div><div class="category-grid">${categories.map(category => `<a class="category-tile" href="/kategori/${category.slug}"><div class="category-visual">${image(category.image,`Inspirasi ${category.name}`,{sizes:'(max-width: 760px) 44vw, (max-width: 1100px) 28vw, 16vw'})}</div><h3>${category.name}<span class="tiny-arrow" aria-hidden="true">↗</span></h3><p>${category.intro}</p></a>`).join('')}</div></div></section>`;
  }

  function productCard(product) {
    return `<article class="product-card" data-catalog-item data-category="${product.category}" data-moments="${product.occasions.join(' ')}" data-search="${esc(`${product.name} ${categoryFor(product).name} ${product.palette}`.toLocaleLowerCase('id'))}"><a class="product-image" href="/produk/${product.slug}" aria-label="Lihat detail ${esc(product.name)}">${image(product.image,`Inspirasi ${product.name} — ${categoryFor(product).name}`)}<span class="image-arrow">${icon('diagonal')}</span></a><p class="product-category">${categoryFor(product).name}</p><h3><a href="/produk/${product.slug}">${product.name}</a></h3><div class="product-card-bottom"><p class="product-price">${price(product)}</p>${productWa(product)}</div></article>`;
  }

  function featuredSection() {
    return `<section class="featured-section" id="produk-pilihan"><div class="section-wrap"><div class="section-head"><div><p class="section-kicker">02 / Pilihan Putri</p><h2 class="section-heading">Yang indah untuk<br><em>yang istimewa.</em></h2></div><div><p class="section-intro">Inspirasi rangkaian untuk melengkapi momenmu.<br>Setiap detail dapat kita bicarakan bersama.</p>${arrowLink('/produk','Lihat semua produk')}</div></div><div class="product-grid">${products.filter(product=>product.featured).map(productCard).join('')}</div><p class="image-note">Visual inspirasi AI. Jenis bunga, ukuran, desain akhir, dan harga dikonfirmasi melalui WhatsApp.</p></div></section>`;
  }

  function customizeTeaserSection() {
    return `<section class="customize-teaser-section" id="kustomisasi"><div class="section-wrap"><div class="customize-teaser-grid"><div><span class="concept-badge">Dalam Pengembangan · In Development</span><h2 class="section-heading">Ceritakan momenmu.<br><em>Kami bantu bentuk bunganya.</em></h2><p class="section-intro">Alih-alih mencari di antara ratusan rangkaian umum, sampaikan momen, anggaran, penerima, warna, dan gaya yang Anda bayangkan. Putri Florist sedang mengembangkan pengalaman kustomisasi berbantu AI untuk mengubah preferensi tersebut menjadi konsep floral yang cocok dan spesifikasi pesanan yang siap diproses florist.</p><div style="margin-top:24px"><a class="button" href="/customize">Jelajahi Alur Kustomisasi${icon('arrow')}</a></div></div><div class="customize-preview-box"><div class="concept-badge-inner">Simulasi Alur Produk (Product Concept)</div><div class="concept-dialogue"><div class="dialogue-input"><span class="dialogue-role">Input Pelanggan:</span><p>“Bunga papan untuk grand opening coffee shop. Budget sekitar Rp700.000. Warna putih dan navy. Modern, minimal, jangan terlalu ramai.”</p></div><div class="dialogue-output"><span class="dialogue-role">Hasil Interpretasi &amp; Order Brief:</span><ul><li><strong>Momen:</strong> Grand opening</li><li><strong>Rentang Anggaran:</strong> Rp500.000 – Rp750.000</li><li><strong>Palet:</strong> White &amp; Navy</li><li><strong>Gaya:</strong> Modern / Minimal</li><li><strong>Rekomendasi:</strong> Congratulatory flower board</li></ul><p class="dialogue-note">Brief terstruktur ini membantu florist memastikan bunga segar dan desain papan dirangkai sesuai ekspektasi pemesan.</p></div></div></div></div></div></section>`;
  }

  function galleryPreviewSection() {
    const previewItems = [
      galleryItems.find(item => item.id === 'g_20') || galleryItems[0],
      galleryItems.find(item => item.id === 'g_47') || galleryItems[1],
      galleryItems.find(item => item.id === 'g_75') || galleryItems[2],
      galleryItems.find(item => item.id === 'g_98') || galleryItems[3],
      galleryItems.find(item => item.id === 'g_149') || galleryItems[4],
      galleryItems.find(item => item.id === 'g_142') || galleryItems[5],
    ];
    return `<section class="gallery-preview-section" id="galeri-preview"><div class="section-wrap"><div class="section-head"><div><p class="section-kicker">Dokumentasi Portofolio</p><h2 class="section-heading">Inspirasi model nyata.<br><em>Untuk rasa yang sesungguhnya.</em></h2></div><div><p class="section-intro">Koleksi referensi portofolio dan inspirasi model rangkaian bunga fisik. Setiap model menampilkan ragam bentuk, komposisi bunga segar, dan palet warna sebagai acuan pesanan custom Anda di Jakarta.</p>${arrowLink('/galeri','Jelajahi galeri lengkap (169 foto)')}</div></div><div class="gallery-preview-grid">${previewItems.map(item => `<a class="gallery-preview-card" href="/galeri?kategori=${item.category}"><div class="gallery-preview-visual"><img src="/assets/gallery/grid-640/${item.image}" srcset="/assets/gallery/grid-320/${item.image} 320w, /assets/gallery/grid-640/${item.image} 640w" sizes="(max-width: 760px) 46vw, (max-width: 1100px) 30vw, 15vw" width="640" height="800" alt="${esc(item.alt)}" loading="lazy" decoding="async"><span class="gallery-card-zoom" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg>Lihat</span></div><div class="gallery-preview-info"><span class="gallery-preview-cat">${esc(item.categoryName)}</span><h3 class="gallery-preview-title">${esc(item.title)}</h3></div></a>`).join('')}</div><div class="gallery-preview-action"><a class="button button-light" href="/galeri">Buka Galeri Lengkap (169 Foto)${icon('arrow')}</a></div></div></section>`;
  }

  function momentsSection() {
    return `<section class="moments-section" id="momen"><div class="section-wrap"><div><p class="section-kicker">03 / Untuk setiap kesempatan</p><h2 class="section-heading">Momen berbeda,<br><em>rasa yang sama.</em></h2><p class="section-intro">Kebahagiaan kecil, pencapaian besar, atau saat kata terasa sulit. Ada rangkaian untuk menemani semuanya.</p></div><div class="moment-grid">${occasions.map(occasion=>`<a class="moment-link" href="/produk?momen=${occasion.slug}"><span class="moment-symbol" aria-hidden="true">${occasion.symbol}</span><h3>${occasion.name}</h3><p>${occasion.line}</p></a>`).join('')}</div></div></section>`;
  }

  function editorialSection() {
    return `<section class="editorial-section" id="tentang-filosofi"><div class="section-wrap editorial-grid"><figure class="editorial-figure">${image('atelier','Visual ilustrasi proses merangkai buket dengan pita',{sizes:'(max-width:760px) 90vw, 45vw'})}<figcaption>Keindahan ada pada perhatian terhadap detail.</figcaption></figure><div class="editorial-copy"><p class="section-kicker">04 / Tentang Putri Florist</p><h2 class="section-heading">Bukan sekadar bunga.<br><em>Sebuah perasaan.</em></h2><p class="section-intro">Ada hal-hal yang terasa lebih hangat saat disampaikan lewat bunga. Rasa terima kasih, rindu, bahagia, juga simpati.</p><p class="section-intro">Putri Florist hadir sejak Januari 2026 untuk membantu Anda menemukan bentuk yang tepat bagi perasaan itu. Dari pilihan warna hingga pesan kecil yang menyertainya, mari merangkai cerita Anda bersama.</p>${arrowLink('/tentang','Kenali Putri Florist')}<p class="editorial-signature">Dengan hati, Putri Florist.</p></div></div></section>`;
  }

  function benefitsSection() {
    return `<section id="keunggulan"><div class="section-wrap"><div class="section-head centered"><p class="section-kicker">Perhatian pada setiap tangkai</p><h2 class="section-heading">Hal kecil yang<br><em>membuatnya berarti.</em></h2></div><div class="benefit-grid">${benefits.map(([symbol,title,text])=>`<div class="benefit-item">${icon(symbol)}<h3>${title}</h3><p>${text}</p></div>`).join('')}</div></div></section>`;
  }

  function testimonialsSection() {
    const reviews = config.testimonials.filter(review=>review.approved && review.name && review.quote);
    return `<section class="testimonials-section" id="testimoni"><div class="section-wrap"><p class="section-kicker">Cerita pelanggan</p>${reviews.length ? `<h2 class="section-heading">Bunga berlalu.<br><em>Kesannya tinggal.</em></h2><div class="review-grid">${reviews.map(review=>`<blockquote><p>“${esc(review.quote)}”</p><cite>${esc(review.name)}</cite></blockquote>`).join('')}</div>` : `<h2 class="section-heading">Setiap rangkaian,<br><em>awal sebuah cerita.</em></h2><p class="section-intro">Cerita dan ulasan pelanggan akan hadir di sini setelah tersedia. Pernah memesan di Putri Florist? Kami ingin mendengar pengalaman Anda.</p>`}${arrowLink(wa('Halo Putri Florist! Saya ingin membagikan pengalaman saya setelah memesan rangkaian bunga.'),'Bagikan pengalamanmu')}</div></section>`;
  }

  function deliverySection() {
    return `<section id="pengiriman"><div class="section-wrap delivery-grid"><div class="delivery-art">${icon('flower')}<span class="delivery-city">${esc(config.city)}</span><p>Dari hati, menuju alamatmu.</p></div><div><p class="section-kicker">Area pengiriman</p><h2 class="section-heading">Kirimkan rasa,<br><em>dekatkan hati.</em></h2><p class="section-intro">Melayani pemesanan untuk area ${esc(config.city)}. Sampaikan alamat tujuan dan tanggal kebutuhan Anda, lalu kami bantu periksa jadwal serta ongkos pengiriman.</p><p class="delivery-note">${config.nearbyAreas.length ? `Area sekitar yang dilayani: ${esc(config.nearbyAreas.join(', '))}.` : 'Untuk wilayah di sekitar Jakarta, ketersediaan layanan perlu dikonfirmasi terlebih dahulu.'}</p><form class="delivery-form" action="https://wa.me/${config.whatsapp}" method="get" data-delivery-form><label for="delivery-area">Ke mana bunganya akan dikirim?</label><input id="delivery-area" name="text" placeholder="Contoh: Tebet, Jakarta Selatan" required maxlength="180" autocomplete="address-level2"><button class="button" type="submit">Cek area kirim${icon('arrow')}</button></form></div></div></section>`;
  }

  function faqSection() {
    return `<section class="faq-section" id="faq"><div class="section-wrap faq-grid"><div><p class="section-kicker">Sedikit bantuan</p><h2 class="section-heading">Sebelum<br><em>memilih bunga.</em></h2><p class="section-intro">Beberapa hal yang mungkin ingin Anda tahu. Untuk pertanyaan lain, kami siap membantu melalui WhatsApp.</p>${arrowLink(wa(generic),'Tanya langsung')}</div><div class="faq-list">${faqs.map(([question,answer])=>`<details><summary>${question}</summary><p>${answer}</p></details>`).join('')}</div></div></section>`;
  }

  function breadcrumbs(items) {
    return `<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Beranda</a>${items.map(([label,url])=>`<span aria-hidden="true">/</span>${url ? `<a href="${url}">${esc(label)}</a>` : `<span aria-current="page">${esc(label)}</span>`}`).join('')}</nav>`;
  }

  const homeContent = companyIntroSection() + categorySection() + featuredSection() + customizeTeaserSection() + galleryPreviewSection() + momentsSection() + editorialSection() + benefitsSection() + testimonialsSection() + deliverySection() + faqSection() + finalCta();
  pages.set('/', shell('/', 'Putri Florist — Custom Flowers & Personalized Floral Design', 'Putri Florist adalah floral-commerce startup Indonesia yang didirikan pada Januari 2026, menyediakan buket bunga, bunga papan, standing flower, dan pemesanan bunga custom.', originalMain.replace('</main>', `<div class="site-content">${homeContent}</div></main>`), {home:true}));

  function catalogPage(category = null) {
    const title = category?.name || 'Semua Rangkaian';
    const path = category ? `/kategori/${category.slug}` : '/produk';
    const collection = category ? products.filter(product=>product.category===category.slug) : products;
    const description = category?.description || 'Temukan buket, bunga papan, standing flower, dan rangkaian lainnya. Pilih sesuai momen dan konsultasikan detailnya dengan kami.';
    const content = `<main class="page-main" id="page-content"><div class="section-wrap page-intro">${breadcrumbs(category ? [['Produk','/produk'],[title]] : [['Produk']])}<div class="catalog-intro"><div><p class="section-kicker">Koleksi Putri Florist</p><h1 class="page-title">${category ? category.name : 'Pilih bunganya.'}<br><em>${category ? category.intro : 'Sampaikan rasanya.'}</em></h1></div><p class="section-intro">${description}</p></div></div><section class="section-wrap catalog-section" aria-label="Katalog rangkaian" data-catalog data-fixed-category="${category?.slug || ''}"><form class="filter-form" action="${path}" method="get"><div class="filter-field"><label for="catalog-search">Cari rangkaian</label><input id="catalog-search" type="search" name="q" placeholder="Nama atau warna bunga…" autocomplete="off"></div><div class="filter-field"><label for="catalog-category">Kategori</label><select id="catalog-category" name="kategori"${category ? ' disabled' : ''}><option value="">Semua kategori</option>${categories.map(item=>`<option value="${item.slug}"${item.slug===category?.slug?' selected':''}>${item.name}</option>`).join('')}</select></div><div class="filter-field"><label for="catalog-moment">Momen</label><select id="catalog-moment" name="momen"><option value="">Semua momen</option>${occasions.map(item=>`<option value="${item.slug}">${item.name}</option>`).join('')}</select></div><button class="filter-reset" type="reset">Reset filter</button></form><div class="catalog-meta"><p data-result-count role="status" aria-live="polite">${collection.length} inspirasi rangkaian</p><p>Visual inspirasi AI · Harga & desain akhir melalui konsultasi</p></div><div class="product-grid">${collection.map(productCard).join('')}</div><div class="empty-state" data-empty hidden><h2 class="section-heading">Belum menemukan yang sesuai?</h2><p>Coba kata kunci atau pilihan lain. Anda juga bisa mendiskusikan rangkaian custom.</p>${waLink('Konsultasi rangkaian')}</div><noscript><p class="image-note">Aktifkan JavaScript untuk memakai filter. Semua rangkaian tersedia di bawah.</p></noscript></section>${finalCta()}</main>`;
    pages.set(path, shell(path, title, description, content));
  }

  function galleryPage() {
    const path = '/galeri';
    const title = 'Galeri Rangkaian Bunga';
    const description = 'Koleksi referensi foto rangkaian bunga nyata untuk inspirasi pemesanan Putri Florist Jakarta. Buket bunga, bunga meja, standing flower, dan bunga papan.';
    const catCount = slug => slug === 'all' ? galleryItems.length : galleryItems.filter(item => item.category === slug).length;

    const content = `<main class="page-main" id="page-content"><div class="section-wrap page-intro">${breadcrumbs([['Galeri']])}<div class="catalog-intro"><div><p class="section-kicker">Portofolio Rangkaian Putri Florist</p><h1 class="page-title">Galeri Inspirasi.<br><em>Setiap bunga, satu cerita.</em></h1></div><p class="section-intro">Koleksi referensi portofolio dan inspirasi model rangkaian bunga fisik. Temukan gaya dan palet warna favorit Anda, lalu konsultasikan ketersediaan bunga segar dan detail pemesanan custom bersama tim florist kami di Jakarta.</p></div></div><section class="section-wrap gallery-section" aria-label="Galeri dokumentasi rangkaian" data-gallery-page><div class="gallery-controls"><div class="gallery-filters" role="tablist" aria-label="Kategori galeri">${galleryCategories.map(cat => `<button type="button" class="gallery-filter-btn${cat.slug === 'all' ? ' is-active' : ''}" role="tab" aria-selected="${cat.slug === 'all'}" data-gallery-filter="${cat.slug}">${cat.name} <span class="filter-count">${catCount(cat.slug)}</span></button>`).join('')}</div><div class="gallery-search-wrap"><label for="gallery-search" class="visually-hidden">Cari foto rangkaian</label><input id="gallery-search" type="search" placeholder="Cari foto rangkaian atau kategori…" autocomplete="off" data-gallery-search></div></div><div class="gallery-meta"><p class="gallery-meta-count" data-gallery-count role="status" aria-live="polite">Menampilkan ${galleryItems.length} foto inspirasi</p><p class="gallery-meta-sub">Referensi portofolio model bunga fisik riil · Konsultasi pesanan langsung via WhatsApp</p></div><div class="gallery-grid" data-gallery-container>${galleryItems.map((item, idx) => `<article class="gallery-card" data-gallery-item data-id="${item.id}" data-category="${item.category}" data-search="${esc(`${item.title} ${item.categoryName}`.toLowerCase())}"><button type="button" class="gallery-card-visual" aria-label="Perbesar foto ${esc(item.title)}" data-gallery-trigger="${item.id}" data-preview="/assets/gallery/preview-1600/${item.image}" data-title="${esc(item.title)}" data-category="${esc(item.categoryName)}"><img src="/assets/gallery/grid-640/${item.image}" srcset="/assets/gallery/grid-320/${item.image} 320w, /assets/gallery/grid-640/${item.image} 640w" sizes="(max-width: 640px) 46vw, (max-width: 1024px) 31vw, 23vw" width="640" height="800" alt="${esc(item.alt)}" loading="${idx < 8 ? 'eager' : 'lazy'}" decoding="async"><span class="gallery-card-zoom" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg>Perbesar</span></button><div class="gallery-card-body"><span class="gallery-card-cat">${esc(item.categoryName)}</span><h3 class="gallery-card-title">${esc(item.title)}</h3><a class="gallery-card-wa" href="${wa(`Halo Putri Florist!\n\nSaya tertarik dengan rangkaian pada galeri:\n${item.title} (${item.categoryName})\nLink foto: ${config.siteUrl.replace(/\/$/, '')}/galeri?id=${item.id}\n\nApakah model seperti ini bisa dipesan untuk area ${config.city}? Boleh dibantu info harga dan detailnya?`)}" target="_blank" rel="noopener noreferrer" data-gallery-wa-item="${item.id}">Tanya rangkaian ini ↗</a></div></article>`).join('')}</div><div class="gallery-empty" data-gallery-empty hidden><h2 class="section-heading">Tidak ada foto yang cocok</h2><p class="section-intro" style="margin-inline:auto">Coba kata kunci lain atau pilih kategori Semua Koleksi.</p><button type="button" class="button button-light" data-gallery-reset>Reset filter</button></div><div class="gallery-pagination" data-gallery-pagination><button type="button" class="button button-light" data-gallery-more>Tampilkan lebih banyak</button></div></section>${finalCta()}</main>`;

    const lightbox = `<dialog class="gallery-lightbox" id="gallery-lightbox" aria-modal="true" aria-labelledby="lightbox-title"><div class="lightbox-inner"><div class="lightbox-header"><div class="lightbox-meta"><span class="lightbox-category" id="lightbox-category">Buket Bunga</span><h2 class="lightbox-title" id="lightbox-title">Buket Bunga #01</h2></div><button type="button" class="close-dialog" data-close-lightbox aria-label="Tutup pratinjau"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="lightbox-stage"><button type="button" class="lightbox-arrow lightbox-prev" data-lightbox-prev aria-label="Foto sebelumnya"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg></button><div class="lightbox-img-wrap"><img class="lightbox-img" id="lightbox-img" src="/assets/gallery/preview-1600/bouquet/image-copy.webp" width="1600" height="2000" alt="Pratinjau Rangkaian Bunga Putri Florist"></div><button type="button" class="lightbox-arrow lightbox-next" data-lightbox-next aria-label="Foto berikutnya"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button></div><div class="lightbox-footer"><span class="lightbox-counter" id="lightbox-counter">1 / 169</span><a class="button" id="lightbox-wa-btn" href="${wa(generic)}" target="_blank" rel="noopener noreferrer">${icon('wa')}Pesan Model Ini via WhatsApp</a></div></div></dialog>`;

    pages.set(path, shell(path, title, description, content, { extra: lightbox }));
  }

  function customizePage() {
    const path = '/customize';
    const title = 'Kustomisasi Bunga Berbantu AI (Dalam Pengembangan)';
    const description = 'Putri Florist sedang mengembangkan pengalaman kustomisasi bunga berbantu AI. Terjemahkan kebutuhan natural menjadi rekomendasi konsep dan order brief terstruktur.';
    const content = `<main class="page-main" id="page-content"><div class="section-wrap page-intro">${breadcrumbs([['Kustomisasi']])}<div class="catalog-intro"><div><span class="concept-badge">Dalam Pengembangan · In Development · Product Concept</span><h1 class="page-title">Ceritakan momenmu.<br><em>Kami bantu bentuk bunganya.</em></h1></div><p class="section-intro">Putri Florist sedang mengembangkan pengalaman kustomisasi bunga berbantu AI (AI-assisted floral customization). Pelanggan mendeskripsikan kebutuhan dalam bahasa natural, dan sistem membantu merumuskan rekomendasi konsep floral, opsi palet warna, serta order brief terstruktur bagi tim florist kami.</p></div></div><section class="section-wrap" style="padding-top:0" aria-label="Status pengembangan kustomisasi"><div class="disclaimer-banner"><h3>Transparansi Status: Fitur AI Sedang Dalam Pengembangan (In Development)</h3><p>Integrasi pemrosesan otomatis berbasis Claude saat ini berstatus <strong>dalam tahap pengembangan teknis dan pengujian alur kerja (workflow)</strong>. Kami tidak mengklaim integrasi API otomatis ini telah aktif di production. Saat ini, konsultasi dan perancangan bunga custom dilayani secara langsung oleh tim florist Putri Florist via WhatsApp menggunakan panduan brief terstruktur di bawah ini.</p></div><div class="section-head" style="margin-top:48px"><div><p class="section-kicker">Alur Kerja Produk</p><h2 class="section-heading">Bagaimana personalisasi<br><em>bunga akan bekerja.</em></h2></div><p class="section-intro">Pendekatan kami memadukan pemahaman kebutuhan berbasis teknologi dengan keahlian perangkaian florist nyata.</p></div><div class="workflow-grid">${customizationWorkflow.map(item => `<div class="workflow-step"><span class="workflow-num">${item.step}</span><h3>${item.title}</h3><p>${item.text}</p></div>`).join('')}</div><div class="section-head" style="margin-top:64px"><div><p class="section-kicker">Simulasi Nyata</p><h2 class="section-heading">Contoh alur dari cerita<br><em>menjadi order brief florist.</em></h2></div><p class="section-intro">Berikut adalah visualisasi bagaimana sistem memetakan kebutuhan pelanggan menjadi instruksi kerja terstruktur.</p></div><div class="concept-demo-wrap"><div class="concept-demo-card"><div class="concept-demo-header"><h3 class="concept-demo-title">Permintaan Pelanggan</h3><span class="concept-demo-tag">Natural Language</span></div><p>“${customizationDemo.customerInput}”</p><div style="margin-top:20px;padding-top:16px;border-top:1px solid #e1e4da;font-size:12px;color:var(--muted)">Pelanggan cukup menceritakan ide dasar tanpa perlu memahami istilah teknis florist.</div></div><div class="concept-demo-card"><div class="concept-demo-header"><h3 class="concept-demo-title">Hasil Interpretasi &amp; Brief</h3><span class="concept-demo-tag">Structured Brief</span></div><ul><li><strong>Momen:</strong> ${customizationDemo.output.occasion}</li><li><strong>Rentang Anggaran:</strong> ${customizationDemo.output.budget}</li><li><strong>Gaya:</strong> ${customizationDemo.output.style}</li><li><strong>Palet Warna:</strong> ${customizationDemo.output.palette}</li><li><strong>Rekomendasi:</strong> ${customizationDemo.output.recommended}</li></ul><div style="margin-top:14px;padding:12px 14px;background:#f3f4ec;border-radius:2px;font-size:12px;color:#45523d"><strong>Saran Detail Konsep:</strong><ul style="margin:6px 0 0;padding-left:16px">${customizationDemo.output.details.map(d => `<li>${d}</li>`).join('')}</ul></div><p style="margin-top:12px;font-size:12px;color:#57634f">${customizationDemo.output.nextStep}</p></div></div><div class="interactive-builder" id="builder"><div class="section-head" style="margin-bottom:24px"><div><span class="concept-badge" style="background:#dce6d2;color:#2e3c27">Kanal Pemesanan Aktif Saat Ini</span><p class="section-kicker">Penyusun Pesanan Custom</p><h2 class="section-heading" style="font-size:clamp(30px, 3.4vw, 44px)">Rancang brief bungamu.<br><em>Langsung terhubung ke WhatsApp florist.</em></h2></div><p class="section-intro">Formulir di bawah ini adalah fitur aktif yang berjalan langsung di peramban Anda. Kami membantu menyusun preferensi Anda menjadi format pesan terstruktur yang siap dikirimkan ke WhatsApp tim florist kami untuk verifikasi ketersediaan bunga dan perhitungan harga.</p></div><form data-customize-form class="builder-grid"><div><label for="c-name">Nama Pemesan</label><input id="c-name" name="name" placeholder="Nama Anda" required maxlength="80"></div><div><label for="c-recipient">Untuk Siapa Rangkaian Ini?</label><input id="c-recipient" name="recipient" placeholder="Contoh: Rekan kerja, pasangan, orang tua" maxlength="100"></div><div><label for="c-category">Format Rangkaian</label><select id="c-category" name="category">${categories.map(c => `<option>${c.name}</option>`).join('')}<option>Butuh Rekomendasi Florist</option></select></div><div><label for="c-occasion">Momen / Acara</label><select id="c-occasion" name="occasion">${occasions.map(o => `<option>${o.name}</option>`).join('')}<option>Lainnya</option></select></div><div><label for="c-budget">Estimasi Anggaran</label><select id="c-budget" name="budget"><option>Di bawah Rp500.000</option><option>Rp500.000 – Rp1.000.000</option><option>Rp1.000.000 – Rp2.000.000</option><option>Di atas Rp2.000.000</option><option>Fleksibel / Sesuai Desain</option></select></div><div><label for="c-palette">Preferensi Warna &amp; Gaya</label><input id="c-palette" name="palette" placeholder="Contoh: Pastel lembut, putih-sage minimalis, merah bold"></div><div class="builder-full"><label for="c-notes">Catatan Khusus atau Pesan Kartu Ucapan</label><textarea id="c-notes" name="notes" placeholder="Ceritakan suasana atau detail tertentu yang Anda inginkan…"></textarea></div><div class="builder-full builder-actions"><button class="button" type="submit">${icon('wa')}Buat Order Brief &amp; Kirim via WhatsApp${icon('diagonal')}</button><p class="builder-note">Brief Anda akan diformat rapi dan dibuka di WhatsApp untuk Anda tinjau sebelum dikirim. Formulir ini tidak menyimpan data pribadi di server.</p></div></form></div><div class="section-head" style="margin-top:64px;border-top:1px solid #dcdfd3;padding-top:48px"><div><p class="section-kicker">Filosofi Kolaborasi</p><h2 class="section-heading">Teknologi membantu memahami.<br><em>Florist nyata yang merangkai.</em></h2></div><p class="section-intro">Kami tidak memposisikan AI sebagai pengganti keahlian florist. Sentuhan estetika, pemilihan kesegaran bunga fisik, dan kehangatan karya tetap berada di tangan florist profesional kami.</p></div></section>${finalCta()}</main>`;
    pages.set(path, shell(path, title, description, content));
  }

  function aboutPage() {
    const path = '/tentang';
    const title = 'Tentang Kami';
    const description = 'Putri Florist adalah floral-commerce startup yang mulai beroperasi pada Januari 2026 di Jakarta, Indonesia. Kami menggabungkan pemesanan digital dengan perangkaian bunga segar oleh florist nyata.';
    const content = `<main class="page-main" id="page-content"><div class="section-wrap about-lead">${breadcrumbs([['Tentang Kami']])}<p class="section-kicker">Profil Putri Florist</p><h1 class="page-title">Kami percaya pada<br><em>bahasa bunga.</em></h1><p class="section-intro">Putri Florist mulai beroperasi pada Januari 2026 di Jakarta, Indonesia. Kami hadir untuk memodernisasi cara pelanggan menemukan, mengkustomisasi, dan memesan rangkaian bunga berkualitas untuk setiap momen berharga.</p></div><section class="about-story"><div class="section-wrap editorial-grid"><figure class="editorial-figure">${image('atelier','Visual ilustrasi tangan merangkai bunga',{eager:true,sizes:'(max-width:760px) 90vw, 45vw'})}<figcaption>Ilustrasi semangat merangkai dengan hati.</figcaption></figure><div class="editorial-copy"><p class="section-kicker">Didirikan Januari 2026 · Jakarta</p><h2 class="section-heading">Setiap perasaan<br><em>layak dirayakan.</em></h2><p>Putri Florist lahir pada awal tahun 2026 dari kebutuhan akan pengalaman memesan bunga yang lebih personal dan transparan. Di industri floral tradisional, pelanggan sering kali harus memilih dari katalog foto kaku tanpa fleksibilitas untuk menyesuaikan anggaran, nuansa warna, atau cerita unik di balik momen tersebut.</p><p>Sebagai floral-commerce startup pada tahap awal (early-stage / bootstrapped), kami sedang membangun jembatan antara kemudahan teknologi digital dengan keahlian pengrajin bunga lokal di Jakarta. Kami ingin setiap buket, bunga papan, atau standing flower yang kami kirimkan benar-benar berbicara mewakili pengirimnya.</p><p>Bagi kami, memilih bunga dimulai dari memahami momennya: untuk siapa rangkaian diberikan, perasaan apa yang ingin disampaikan, dan suasana apa yang dibayangkan. Dari percakapan itu, kami membantu menemukan bentuk dan palet yang tepat sebelum bunga segar dirangkai.</p><p class="editorial-signature">Dengan hati, Putri Florist.</p></div></div></section><section class="section-wrap" style="padding-top:0"><div class="section-head"><div><p class="section-kicker">Pendekatan Kami</p><h2 class="section-heading">Sentuhan florist nyata,<br><em>didukung teknologi.</em></h2></div><p class="section-intro">Teknologi membantu kami memahami preferensi dan mengorganisir pesanan pelanggan. Florist kami mengubah ide-ide tersebut menjadi rangkaian fisik yang berkesan.</p></div><div class="workflow-grid" style="margin-top:24px"><div class="workflow-step"><span class="workflow-num">01</span><h3>Eksplorasi Personal</h3><p>Pelanggan dapat menjelajahi inspirasi atau menyampaikan preferensi unik untuk momen khusus.</p></div><div class="workflow-step"><span class="workflow-num">02</span><h3>Pengembangan AI</h3><p>Kami sedang mengembangkan sistem asistensi AI untuk menerjemahkan bahasa natural menjadi brief bunga terstruktur.</p></div><div class="workflow-step"><span class="workflow-num">03</span><h3>Florist Berpengalaman</h3><p>Setiap rangkaian dirangkai langsung oleh tangan florist nyata menggunakan bunga segar pilihan.</p></div><div class="workflow-step"><span class="workflow-num">04</span><h3>Pengantaran Jakarta</h3><p>Rangkaian dikirimkan dengan hati-hati ke alamat penerima di Jakarta dan sekitarnya tepat waktu.</p></div></div></section><section class="section-wrap" style="padding-top:0"><div class="company-facts-card" style="max-width:860px;margin-inline:auto"><h2 class="facts-title" style="font-size:26px">Fakta Perusahaan &amp; Informasi Bisnis</h2><dl class="facts-list">${companyFacts.map(fact => `<div><dt>${esc(fact.label)}</dt><dd>${esc(fact.value)}</dd></div>`).join('')}</dl></div></section><section class="featured-section"><div class="section-wrap"><p class="section-kicker">Cara memesan</p><h2 class="section-heading">Sesederhana<br><em>menyampaikan rasa.</em></h2><div class="steps-grid">${[['01','Pilih inspirasi atau kustomisasi','Jelajahi koleksi kami atau gunakan form kustomisasi untuk merancang konsep bunga yang Anda bayangkan.'],['02','Konsultasi via WhatsApp','Hubungi tim kami dengan detail momen, anggaran, tanggal kebutuhan, dan alamat tujuan pengiriman.'],['03','Konfirmasi & perangkaian','Sepakati desain, harga final, dan ketersediaan bunga segar sebelum pesanan Anda dirangkai dan dikirimkan.']].map(([number,title,text])=>`<div><span class="step-number">${number}</span><h3>${title}</h3><p>${text}</p></div>`).join('')}</div></div></section>${benefitsSection()}${finalCta()}</main>`;
    pages.set(path, shell(path, title, description, content));
  }

  function contactPage() {
    const path = '/kontak';
    const title = 'Kontak & Pemesanan';
    const description = 'Hubungi Putri Florist melalui WhatsApp resmi untuk konsultasi buket bunga, bunga papan, standing flower, dan layanan pengiriman di area Jakarta.';
    const content = `<main class="page-main" id="page-content"><div class="section-wrap page-intro">${breadcrumbs([['Kontak']])}</div><div class="section-wrap contact-grid" style="padding-top:0"><div class="contact-info"><p class="section-kicker">Kontak Putri Florist</p><h1 class="page-title">Semua berawal<br><em>dari cerita kecil.</em></h1><p class="section-intro">Ada rangkaian yang ingin Anda pesan, referensi yang ingin dibagikan, atau sekadar ingin bertanya? Mari berbincang langsung melalui WhatsApp resmi kami.</p><dl class="contact-details"><div><dt>WhatsApp Resmi</dt><dd><a class="contact-phone" href="${wa(generic)}" target="_blank" rel="noopener noreferrer">${displayPhone} ↗</a></dd></div><div><dt>Area Layanan</dt><dd>${esc(config.city)}, Indonesia<br><small>Pengiriman kurir bunga segar menjangkau Jakarta dan area sekitar yang disepakati.</small></dd></div><div><dt>Email Bisnis</dt><dd>hello@putriflorist.id<br><small>Status: Kotak surat domain sedang dikonfigurasi. Untuk respon instan, hubungi WhatsApp.</small></dd></div><div><dt>Jam Layanan</dt><dd>Setiap hari, 08:00 – 21:00 WIB<br><small>Konsultasi dan konfirmasi pesanan aktif via WhatsApp.</small></dd></div><div><dt>Entitas Bisnis</dt><dd>Putri Florist (Didirikan Januari 2026 di Indonesia)<br><small>Early-stage floral commerce startup.</small></dd></div></dl></div><form class="contact-form" data-contact-form><h2 class="section-heading">Mari merangkai ceritamu.</h2><p>Isi kebutuhan singkat Anda. Detail ini akan dibawa ke WhatsApp agar percakapan lebih mudah.</p><label for="contact-name">Nama Anda</label><input id="contact-name" name="name" autocomplete="name" required maxlength="80" placeholder="Nama panggilan"><label for="contact-category">Pilihan rangkaian</label><select id="contact-category" name="category">${categories.map(category=>`<option>${category.name}</option>`).join('')}<option>Kustomisasi / Butuh rekomendasi</option></select><label for="contact-date">Tanggal kebutuhan (opsional)</label><input id="contact-date" type="date" name="date"><label for="contact-message">Ceritakan kebutuhan Anda</label><textarea id="contact-message" name="message" maxlength="1500" required placeholder="Momen, warna favorit, anggaran, dan area pengiriman…"></textarea><button class="button" type="submit">${icon('wa')}Lanjutkan ke WhatsApp${icon('diagonal')}</button><p class="form-note">WhatsApp terbuka dengan pesan yang bisa Anda periksa sebelum dikirim. Formulir ini tidak menyimpan data di server.</p></form></div>${deliverySection()}${faqSection()}${finalCta()}</main>`;
    pages.set(path, shell(path, title, description, content));
  }

  function privacyPage() {
    const path = '/privacy';
    const title = 'Kebijakan Privasi';
    const description = 'Kebijakan privasi Putri Florist mengenai aliran data pemesanan, ketiadaan cookie pelacak, infrastruktur Cloudflare, dan proteksi komunikasi.';
    const content = `<main class="page-main" id="page-content"><div class="section-wrap legal-wrap page-intro">${breadcrumbs([['Kebijakan Privasi']])}<p class="section-kicker">Kebijakan &amp; Keamanan Data</p><h1 class="page-title">Kebijakan Privasi</h1><p class="legal-lead">Terakhir diperbarui: Oktober 2026 · Berlaku untuk seluruh pengunjung dan layanan Putri Florist (putriflorist.id).</p><article class="legal-article"><section><h2>1. Pendahuluan</h2><p>Putri Florist ("kami") adalah floral-commerce startup yang mulai beroperasi pada Januari 2026 di Jakarta, Indonesia. Kami berkomitmen untuk menjaga privasi Anda dengan prinsip transparansi penuh dan meminimalkan pengumpulan data (data minimization). Kebijakan Privasi ini menjelaskan aliran data aktual saat Anda mengakses situs putriflorist.id dan berkomunikasi dengan kami.</p></section><section><h2>2. Aliran Data &amp; Pemrosesan Formulir Sisi Klien (Client-Side)</h2><p>Situs putriflorist.id dirancang secara statis dan tidak memiliki basis data (database) server yang mengumpulkan entri pribadi Anda saat menjelajah:</p><ul><li><strong>Pemrosesan Formulir Lokal:</strong> Formulir konsultasi di halaman Kontak dan Kustomisasi diproses murni oleh JavaScript di peramban (client-side DOM). Saat Anda menekan tombol kirim, data tersebut diformat menjadi tautan pesan teks dan dibuka langsung ke aplikasi WhatsApp Anda. Kami tidak menyimpan draf pesan tersebut di server web.</li><li><strong>Ketiadaan Cookie Pelacak &amp; Profiling:</strong> Kami tidak menggunakan cookie pelacak pihak ketiga, tidak memasang piksel pemasaran (seperti Meta Pixel atau pelacak analitik perilaku), dan tidak menjual data Anda kepada broker periklanan.</li></ul></section><section><h2>3. Infrastruktur &amp; Layanan Pihak Ketiga</h2><p>Untuk menyajikan situs secara andal dan cepat, kami menggunakan layanan pihak ketiga dengan cakupan teknis berikut:</p><ul><li><strong>Cloudflare Pages &amp; CDN (Cloudflare, Inc.):</strong> Situs ini dihosting dan didistribusikan secara global melalui infrastruktur Cloudflare. Server Cloudflare dapat memproses log koneksi teknis standar (seperti alamat IP, jenis peramban, dan waktu akses) untuk tujuan keamanan DDoS, caching, dan keandalan perutean jaringan.</li><li><strong>Google Fonts (Google LLC):</strong> Berkas font tipografi (Cormorant Garamond dan Manrope) dimuat dari server Google Fonts untuk menyajikan tampilan antarmuka.</li><li><strong>WhatsApp (Meta Platforms, Inc.):</strong> Saluran transaksi dan konsultasi utama kami berlangsung di WhatsApp. Seluruh komunikasi pesan, nomor telepon, dan lampiran foto yang Anda kirimkan di WhatsApp tunduk pada ketentuan privasi Meta dan diamankan dengan enkripsi end-to-end.</li></ul></section><section><h2>4. Penggunaan Informasi Pesanan</h2><p>Informasi pesanan yang Anda kirimkan ke tim kami melalui WhatsApp (seperti nama, alamat tujuan di Jakarta, pesan ucapan, dan anggaran) semata-mata digunakan untuk:</p><ul><li>Menyiapkan rekomendasi konsep dan menyepakati desain rangkaian bunga segar.</li><li>Merangkai pesanan fisik oleh tim florist kami.</li><li>Menjalankan pengiriman kurir ke alamat tujuan yang Anda tentukan.</li><li>Pencatatan pembukuan internal dan konfirmasi pembayaran perbankan.</li></ul></section><section><h2>5. Transparansi Roadmap Fitur AI</h2><p>Putri Florist sedang merancang dan mengembangkan pengalaman kustomisasi bunga berbantu AI (AI-assisted customization) untuk membantu memetakan bahasa natural pelanggan menjadi order brief terstruktur. <strong>Status saat ini adalah dalam tahap pengembangan (in development).</strong> Kami tidak mengirimkan data pengguna atau percakapan pribadi pelanggan ke model/API AI pihak ketiga mana pun pada saat ini. Jika integrasi AI diaktifkan di masa depan, arsitektur data akan diperbarui dan data sensitif (seperti nama lengkap, nomor telepon, atau alamat fisik) tidak akan diteruskan ke pemroses AI.</p></section><section><h2>6. Hak Anda &amp; Kontak</h2><p>Anda berhak meminta penghapusan riwayat percakapan atau data kontak pesanan dari catatan WhatsApp tim kami kapan saja setelah pemesanan selesai. Untuk pertanyaan atau permintaan terkait data Anda, hubungi admin resmi kami melalui WhatsApp (+62 857-7371-0841).</p></section></article></div>${finalCta()}</main>`;
    pages.set(path, shell(path, title, description, content));
  }

  function termsPage() {
    const path = '/terms';
    const title = 'Syarat & Ketentuan';
    const description = 'Syarat dan ketentuan layanan Putri Florist untuk pemesanan rangkaian bunga segar, kustomisasi desain, pengantaran, dan kebijakan pesanan di Jakarta.';
    const content = `<main class="page-main" id="page-content"><div class="section-wrap legal-wrap page-intro">${breadcrumbs([['Syarat & Ketentuan']])}<p class="section-kicker">Ketentuan Layanan</p><h1 class="page-title">Syarat &amp; Ketentuan</h1><p class="legal-lead">Terakhir diperbarui: Oktober 2026 · Berlaku untuk seluruh pemesanan rangkaian bunga di Putri Florist.</p><article class="legal-article"><section><h2>1. Gambaran Umum</h2><p>Putri Florist adalah usaha floral commerce digital yang didirikan pada Januari 2026 di Jakarta, Indonesia. Dengan mengakses situs putriflorist.id atau memesan rangkaian bunga melalui kanal resmi kami, Anda menyetujui syarat dan ketentuan di bawah ini.</p></section><section><h2>2. Pemesanan &amp; Konsultasi</h2><ul><li>Seluruh pesanan diawali dengan konsultasi melalui WhatsApp resmi untuk memastikan detail kebutuhan, ketersediaan bahan bunga segar, dan waktu pengiriman.</li><li>Pesanan dianggap resmi (confirmed) setelah pemesan menyetujui rincian pesanan dan menyelesaikan pembayaran sesuai kesepakatan.</li></ul></section><section><h2>3. Sifat Alami Bunga Segar (Natural Products)</h2><p>Bunga segar adalah produk alam yang ketersediaannya dipengaruhi oleh musim dan pasokan pasar bunga segar lokal:</p><ul><li>Foto katalog dan simulasi visual merupakan referensi inspirasi konsep, bukan salinan identik 100%.</li><li>Jika ada jenis bunga atau dedaunan tertentu yang tidak tersedia atau kualitasnya dinilai kurang segar pada hari perangkaian, florist kami berhak melakukan substitusi dengan jenis bunga setara yang senada setelah mengonfirmasikannya kepada pemesan.</li></ul></section><section><h2>4. Harga &amp; Pembayaran</h2><ul><li>Harga yang tertera pada katalog atau formulir adalah perkiraan awal. Harga final disepakati bersama berdasarkan dimensi rangkaian, jenis bunga yang dipilih, serta ongkos kirim ke alamat tujuan.</li><li>Pembayaran dilakukan melalui transfer bank resmi yang diinstruksikan oleh admin WhatsApp resmi kami sebelum proses perangkaian bunga dimulai.</li></ul></section><section><h2>5. Pengiriman &amp; Penerimaan</h2><ul><li>Layanan pengiriman mencakup area Jakarta dan wilayah sekitarnya yang telah disepakati.</li><li>Pemesan bertanggung jawab memberikan alamat tujuan yang lengkap, patokan lokasi, serta nomor kontak penerima yang aktif.</li><li>Keterlambatan yang disebabkan oleh kendala di luar kendali wajar kami (seperti cuaca ekstrem atau penutupan jalanan mendadak) akan segera kami komunikasikan kepada pemesan.</li></ul></section><section><h2>6. Pembatalan &amp; Pengembalian</h2><p>Karena bunga segar bersifat mudah rusak (perishable) dan dirangkai secara custom sesuai pesanan, pesanan yang sudah mulai dirangkai atau telah dalam perjalanan pengiriman tidak dapat dibatalkan atau dikembalikan secara sepihak. Segala kendala kualitas fisik saat penerimaan harus dilaporkan dalam kurun waktu 3 jam setelah bunga diterima disertai bukti foto.</p></section><section><h2>7. Kontak Resmi</h2><p>Untuk klarifikasi atau pertanyaan seputar syarat dan ketentuan ini, hubungi tim kami melalui WhatsApp resmi Putri Florist (+62 857-7371-0841).</p></section></article></div>${finalCta()}</main>`;
    pages.set(path, shell(path, title, description, content));
  }

  catalogPage();
  categories.forEach(catalogPage);
  galleryPage();
  customizePage();
  aboutPage();
  contactPage();
  privacyPage();
  termsPage();

  products.forEach(product => {
    const category = categoryFor(product);
    const path = `/produk/${product.slug}`;
    const related = products.filter(item=>item.slug!==product.slug).sort((a,b)=>Number(b.occasions.some(moment=>product.occasions.includes(moment)))-Number(a.occasions.some(moment=>product.occasions.includes(moment)))).slice(0,4);
    const body = `<main class="page-main" id="page-content"><div class="section-wrap product-page">${breadcrumbs([['Produk','/produk'],[category.name,`/kategori/${category.slug}`],[product.name]])}<div class="product-layout"><div class="product-gallery"><button class="gallery-main" type="button" aria-label="Perbesar foto ${product.name}" data-open-gallery>${image(product.image,`Inspirasi ${product.name}`,{eager:true,sizes:'(max-width:760px) 90vw, 50vw'})}</button><div class="gallery-thumbs" aria-label="Pilihan tampilan foto"><button class="gallery-thumb" type="button" data-gallery-view="full" aria-pressed="true" aria-label="Lihat rangkaian utuh">${image(product.image,'',{sizes:'70px'})}</button><button class="gallery-thumb detail" type="button" data-gallery-view="detail" aria-pressed="false" aria-label="Lihat detail bunga">${image(product.image,'',{sizes:'70px'})}</button></div><p class="gallery-help">Rangkaian utuh / detail bunga · Klik foto untuk memperbesar.</p></div><div class="product-info"><a class="section-kicker" href="/kategori/${category.slug}">${category.name}</a><h1 class="page-title">${product.name}</h1><p class="price-display">${price(product)}</p><p class="price-note">Harga mengikuti jenis bunga, ukuran, dan desain yang disepakati.</p><p class="product-description">${product.description}</p><p class="palette-label">Palet inspirasi: ${product.palette}</p><ul class="product-facts">${product.details.map(detail=>`<li>${detail}</li>`).join('')}</ul><div class="custom-note"><h2 class="section-heading">Jadikan lebih personal.</h2><p>Warna, ukuran, pita, dan pesan ucapan dapat dikonsultasikan. Ceritakan referensi, anggaran, dan tanggal kebutuhan Anda.</p></div>${productWa(product,'button','Pesan via WhatsApp')}<p class="product-image-disclosure">${product.isConcept ? 'Visual ini dibuat dengan AI sebagai inspirasi, bukan dokumentasi produk siap stok. ' : ''}Jenis bunga, komposisi, ukuran, harga, dan waktu pengiriman dikonfirmasi sebelum pemesanan.</p></div></div></div><section class="related-section"><div class="section-wrap"><div class="section-head"><div><p class="section-kicker">Cerita lainnya</p><h2 class="section-heading">Mungkin kamu<br><em>juga menyukainya.</em></h2></div>${arrowLink('/produk','Kembali ke koleksi')}</div><div class="product-grid">${related.map(productCard).join('')}</div></div></section>${finalCta()}</main>`;
    const lightbox = `<dialog class="lightbox" id="gallery-dialog" aria-labelledby="gallery-title"><h2 id="gallery-title">${product.name} — visual inspirasi</h2><button class="close-dialog" type="button" data-close-gallery aria-label="Tutup foto"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button>${image(product.image,`Inspirasi ${product.name} diperbesar`,{sizes:'90vw'})}</dialog>`;
    pages.set(path,shell(path,`${product.name} — ${category.name}`,product.description,body,{extra:lightbox,imageKey:product.image}));
  });

  pages.set('/404', shell('/404', 'Halaman Tidak Ditemukan', 'Halaman yang Anda cari tidak ditemukan di situs Putri Florist.', `<main class="page-main" id="page-content"><div class="section-wrap not-found"><p class="section-kicker">404 / Sepertinya tersesat</p><h1 class="page-title">Mari kembali<br><em>ke bunga-bunga.</em></h1><p class="section-intro" style="margin-inline:auto">Halaman ini belum tersedia atau alamatnya telah berubah.</p><a class="button" href="/produk">Jelajahi rangkaian${icon('arrow')}</a></div></main>`));

  return pages;
}
